CREATE TABLE users (
 id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 100), email TEXT NOT NULL,
 password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','teacher','student')),
 phone TEXT NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE,
 created TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX users_email_unique ON users(lower(email));
CREATE TABLE teachers(user_id INTEGER PRIMARY KEY REFERENCES users(id),specialty TEXT NOT NULL,registration TEXT NOT NULL DEFAULT '');
CREATE TABLE membership_plans(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE,description TEXT NOT NULL,price NUMERIC(12,2) NOT NULL CHECK(price>=0),months INTEGER NOT NULL CHECK(months BETWEEN 1 AND 36),benefits TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE students(user_id INTEGER PRIMARY KEY REFERENCES users(id),teacher_id INTEGER NOT NULL REFERENCES teachers(user_id),birthday DATE,enrollment DATE NOT NULL DEFAULT CURRENT_DATE,objective TEXT NOT NULL DEFAULT '',consent BOOLEAN NOT NULL DEFAULT FALSE);
CREATE INDEX student_teacher ON students(teacher_id);
CREATE TABLE subscriptions(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(user_id),plan_id INTEGER NOT NULL REFERENCES membership_plans(id),start DATE NOT NULL DEFAULT CURRENT_DATE,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE UNIQUE INDEX one_active_subscription ON subscriptions(student_id) WHERE active;
CREATE TABLE exercises(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,muscle TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'Musculação',equipment TEXT NOT NULL,level TEXT NOT NULL,instructions TEXT NOT NULL,precautions TEXT NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE workouts(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(user_id),teacher_id INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,objective TEXT NOT NULL,division TEXT NOT NULL CHECK(division IN ('A','B','C','D','E','F','G')),notes TEXT NOT NULL DEFAULT '',created TIMESTAMPTZ NOT NULL DEFAULT now(),updated TIMESTAMPTZ NOT NULL DEFAULT now(),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE INDEX workout_student ON workouts(student_id);
CREATE TABLE workout_exercises(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,workout_id INTEGER NOT NULL REFERENCES workouts(id),exercise_id INTEGER NOT NULL REFERENCES exercises(id),position INTEGER NOT NULL,sets INTEGER NOT NULL CHECK(sets BETWEEN 1 AND 20),reps TEXT NOT NULL,load NUMERIC(8,2) NOT NULL CHECK(load>=0),rest INTEGER NOT NULL CHECK(rest BETWEEN 0 AND 1800),UNIQUE(workout_id,position));
CREATE TABLE workout_versions(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,workout_id INTEGER NOT NULL REFERENCES workouts(id),snapshot JSONB NOT NULL,created TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE workout_sessions(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,workout_id INTEGER NOT NULL REFERENCES workouts(id),student_id INTEGER NOT NULL REFERENCES students(user_id),created TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE workout_logs(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,session_id INTEGER NOT NULL REFERENCES workout_sessions(id),exercise_id INTEGER NOT NULL REFERENCES exercises(id),name TEXT NOT NULL,sets INTEGER NOT NULL CHECK(sets>0),reps INTEGER NOT NULL CHECK(reps>0),load NUMERIC(8,2) NOT NULL CHECK(load>=0));
CREATE TABLE assessments(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(user_id),teacher_id INTEGER NOT NULL REFERENCES users(id),date DATE NOT NULL,weight NUMERIC(6,2) NOT NULL CHECK(weight BETWEEN 10 AND 500),height NUMERIC(6,2) NOT NULL CHECK(height BETWEEN 50 AND 250),waist NUMERIC(6,2) NOT NULL CHECK(waist BETWEEN 20 AND 300),notes TEXT NOT NULL,objective TEXT NOT NULL,next_date DATE NOT NULL,CHECK(next_date>=date));
CREATE INDEX assessment_student ON assessments(student_id,date);
CREATE TABLE attendance(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(user_id),day DATE NOT NULL,time TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),UNIQUE(student_id,day));
CREATE TABLE payments(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(user_id),subscription_id INTEGER NOT NULL REFERENCES subscriptions(id),amount NUMERIC(12,2) NOT NULL CHECK(amount>=0),due DATE NOT NULL,status TEXT NOT NULL DEFAULT 'Pendente' CHECK(status IN ('Pendente','Pago','Cancelado')),paid_at TIMESTAMPTZ,method TEXT NOT NULL DEFAULT '',CHECK((status='Pago')=(paid_at IS NOT NULL)));
CREATE UNIQUE INDEX payment_subscription_due ON payments(subscription_id,due) WHERE status<>'Cancelado';
CREATE INDEX payment_due ON payments(due,status);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires TIMESTAMPTZ NOT NULL);
CREATE INDEX session_expiry ON sessions(expires);
CREATE TABLE notifications(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,created TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,entity_id INTEGER,created TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),gym_name TEXT NOT NULL DEFAULT 'GymFlow Studio',phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '');
INSERT INTO settings(id) VALUES(1);

-- Identity is set with transaction-local parameters by the trusted server.
CREATE FUNCTION gymflow_is_admin() RETURNS BOOLEAN LANGUAGE SQL STABLE AS $$ SELECT current_setting('gymflow.role',true)='admin' OR current_setting('gymflow.system',true)='on' $$;
CREATE FUNCTION gymflow_uid() RETURNS INTEGER LANGUAGE SQL STABLE AS $$ SELECT NULLIF(current_setting('gymflow.user_id',true),'')::INTEGER $$;
ALTER TABLE students ENABLE ROW LEVEL SECURITY;
ALTER TABLE students FORCE ROW LEVEL SECURITY;
CREATE POLICY students_read ON students FOR SELECT USING(gymflow_is_admin() OR user_id=gymflow_uid() OR (current_setting('gymflow.role',true)='teacher' AND teacher_id=gymflow_uid()));
CREATE POLICY students_write ON students FOR ALL USING(gymflow_is_admin()) WITH CHECK(gymflow_is_admin());
CREATE FUNCTION gymflow_student_visible(sid INTEGER) RETURNS BOOLEAN LANGUAGE SQL STABLE AS $$ SELECT gymflow_is_admin() OR EXISTS(SELECT 1 FROM students WHERE user_id=sid) $$;
